import{_ as a,o,c as t,a2 as i}from"./chunks/framework.lxr64Vqo.js";const g=JSON.parse('{"title":"AI & Custom Catalogs","description":"","frontmatter":{},"headers":[],"relativePath":"guide/ai-catalogs.md","filePath":"guide/ai-catalogs.md","lastUpdated":1795114725000}'),r={name:"guide/ai-catalogs.md"};function s(l,e,n,c,d,u){return o(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="ai-custom-catalogs" tabindex="-1">AI &amp; Custom Catalogs <a class="header-anchor" href="#ai-custom-catalogs" aria-label="Permalink to &quot;AI &amp; Custom Catalogs&quot;">​</a></h1><p>One of NoxMedia&#39;s core capabilities is <strong>Dynamic Custom Shelves</strong>. Rather than relying on generic genre lists, you can create tailored collections curated by AI or fine-tuned rules that reflect your exact viewing tastes.</p><hr><h2 id="what-are-custom-catalogs" tabindex="-1">What are Custom Catalogs? <a class="header-anchor" href="#what-are-custom-catalogs" aria-label="Permalink to &quot;What are Custom Catalogs?&quot;">​</a></h2><p>Custom catalogs are dynamic playlists that index and filter your Telegram library on the fly.</p><p>Examples of popular shelves:</p><ul><li><em>Murder Mystery &amp; Dark Investigative</em></li><li><em>Sci-Fi Space Operas &amp; Cyberpunk</em></li><li><em>A24 &amp; Independent Cinema</em></li><li><em>Peak Animation Anime</em></li><li><em>4K Dolby Vision Reference Quality</em></li></ul><hr><h2 id="ai-powered-curation-gemini-openrouter" tabindex="-1">AI-Powered Curation (Gemini &amp; OpenRouter) <a class="header-anchor" href="#ai-powered-curation-gemini-openrouter" aria-label="Permalink to &quot;AI-Powered Curation (Gemini &amp; OpenRouter)&quot;">​</a></h2><p>NoxMedia integrates directly with large language models to curate playlists from your indexed media:</p><ol><li>In NoxMedia Settings, add your free <strong>Google Gemini API Key</strong> or <strong>OpenRouter API Key</strong>.</li><li>Navigate to <strong>Catalogs</strong> -&gt; <strong>Create New Shelf</strong> -&gt; <strong>AI Assistant</strong>.</li><li>Enter your prompt in plain language: <blockquote><p><em>&quot;Find all psychological thrillers, neo-noir, and investigative murder mysteries with dark atmospheres and high suspense.&quot;</em></p></blockquote></li><li>NoxMedia&#39;s AI analyzes your indexed database, cross-references movie themes, plots, and tags, and builds your shelf automatically.</li></ol><hr><h2 id="manual-rule-based-filters" tabindex="-1">Manual Rule-Based Filters <a class="header-anchor" href="#manual-rule-based-filters" aria-label="Permalink to &quot;Manual Rule-Based Filters&quot;">​</a></h2><p>If you prefer exact control, you can create shelves based on explicit criteria:</p><ul><li><strong>Genre Matching</strong>: Include or exclude genres (e.g., <code>Sci-Fi</code> + <code>Thriller</code>, exclude <code>Horror</code>).</li><li><strong>Resolution &amp; Quality</strong>: Filter strictly for <code>4K UHD</code> or <code>HDR10 / Dolby Vision</code> files.</li><li><strong>Year &amp; Decades</strong>: Create era-specific collections (e.g., <em>80s Action</em>, <em>90s Nostalgia</em>).</li><li><strong>Ratings Threshold</strong>: Minimum TMDB score (e.g., <code>Score &gt;= 7.5</code>).</li><li><strong>Keywords &amp; Directors</strong>: Filter by tags like <code>Christopher Nolan</code>, <code>Studio Ghibli</code>, <code>Time Travel</code>.</li></ul><hr><h2 id="cross-client-synchronization" tabindex="-1">Cross-Client Synchronization <a class="header-anchor" href="#cross-client-synchronization" aria-label="Permalink to &quot;Cross-Client Synchronization&quot;">​</a></h2><p>Once a shelf is created in NoxMedia, it is immediately broadcast across your connected players:</p><ul><li><strong>Infuse</strong>: Appears as a dedicated folder in <strong>Files -&gt; NoxMedia</strong>. Star it to display it directly on your Apple TV or iPad Home Screen.</li><li><strong>Vesper</strong>: Appears inside your connected server libraries.</li><li><strong>Nuvio</strong>: Seamlessly integrates into your custom provider feeds on the home board.</li></ul>',19)])])}const p=a(r,[["render",s]]);export{g as __pageData,p as default};
